CREATE OR REPLACE FUNCTION public.fn_get_product_ledger(p_product_id uuid, p_limit integer DEFAULT 50)  RETURNS TABLE(id uuid, material_product_id uuid, location_id uuid, transaction_type character varying, quantity_delta integer, available_delta integer, reserved_delta integer, on_loan_delta integer, reference_type character varying, reference_id uuid, notes text, performed_by_user_id uuid, performed_by_email character varying, created_at timestamp with time zone, product_name character varying, product_sku character varying)  LANGUAGE sql  STABLE AS $function$     SELECT          l.id, l.material_product_id, l.location_id, l.transaction_type,         l.quantity_delta, l.available_delta, l.reserved_delta, l.on_loan_delta,         l.reference_type, l.reference_id, l.notes,         l.performed_by_user_id, l.performed_by_email, l.created_at,         p.name AS product_name, p.sku AS product_sku     FROM inventory_ledger l     JOIN material_products p ON l.material_product_id = p.id     WHERE l.material_product_id = p_product_id     ORDER BY l.created_at DESC     LIMIT p_limit; $function$ ;
